mapper.sql:
AND ticket_id IN (
    SELECT scoped_ticket.id FROM support_tickets scoped_ticket
    WHERE scoped_ticket.tenant_id = #{tenantId}



)

tenant_id = #{tenantId}


    AND knowledge_base_id = #{knowledgeBaseId}


    AND status = #{status}


    AND priority = #{priority}


    AND assignee_id = #{assigneeId}


    AND due_at IS NOT NULL
    AND due_at < CURRENT_TIMESTAMP(6)
    AND status NOT IN ('RESOLVED', 'CLOSED')


    AND (
        ticket_no LIKE CONCAT('%', #{keyword}, '%')
        OR customer_name LIKE CONCAT('%', #{keyword}, '%')
        OR issue_summary LIKE CONCAT('%', #{keyword}, '%')
        OR customer_question LIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(order_no, '') LIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(product_name, '') LIKE CONCAT('%', #{keyword}, '%')
    )

mapper.select:
SELECT COUNT(t.id) AS total, COALESCE(SUM(CASE WHEN t.status = 'OPEN' THEN 1 ELSE 0 END), 0) AS open, COALESCE(SUM(CASE WHEN t.status = 'IN_PROGRESS' THEN 1 ELSE 0 END), 0) AS in_progress, COALESCE(SUM(CASE WHEN t.status = 'WAITING_CUSTOMER' THEN 1 ELSE 0 END), 0) AS waiting_customer, COALESCE(SUM(CASE WHEN t.status = 'RESOLVED' THEN 1 ELSE 0 END), 0) AS resolved, COALESCE(SUM(CASE WHEN t.status = 'CLOSED' THEN 1 ELSE 0 END), 0) AS closed, COALESCE(SUM(CASE WHEN t.due_at IS NOT NULL AND t.due_at < CURRENT_TIMESTAMP(6) AND t.status NOT IN ('RESOLVED', 'CLOSED') THEN 1 ELSE 0 END), 0) AS overdue, CAST(ROUND(AVG(CASE WHEN first_reply.first_reply_at IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, t.created_at, first_reply.first_reply_at) ELSE NULL END)) AS SIGNED) AS avg_first_response_minutes, CAST(ROUND( COALESCE(SUM(CASE WHEN t.status IN ('RESOLVED', 'CLOSED') AND t.due_at IS NOT NULL AND t.resolved_at IS NOT NULL AND t.resolved_at <= t.due_at THEN 1 ELSE 0 END), 0) * 100.0 / NULLIF(COALESCE(SUM(CASE WHEN t.status IN ('RESOLVED', 'CLOSED') AND t.due_at IS NOT NULL THEN 1 ELSE 0 END), 0), 0) ) AS SIGNED) AS sla_attainment_rate FROM support_tickets t LEFT JOIN ( SELECT ticket_id, MIN(created_at) AS first_reply_at FROM support_ticket_events WHERE tenant_id = #{tenantId}
AND event_type = 'AGENT_REPLY_SENT' GROUP BY ticket_id ) first_reply ON first_reply.ticket_id = t.id WHERE t.tenant_id = #{tenantId}
AND t.created_at >= #{startAt} AND t.created_at < #{endAt}

SELECT
    COALESCE(SUM(CASE WHEN event_type = 'AI_REPLY_GENERATED' THEN 1 ELSE 0 END), 0) AS ai_reply_generated,
    COALESCE(SUM(CASE WHEN event_type = 'AGENT_REPLY_SENT' THEN 1 ELSE 0 END), 0) AS outgoing_replies,
    COALESCE(SUM(CASE WHEN event_type = 'CUSTOMER_MESSAGE' THEN 1 ELSE 0 END), 0) AS customer_messages
FROM support_ticket_events
WHERE tenant_id = #{tenantId}

  AND created_at >= #{startAt}
  AND created_at < #{endAt}

SELECT category AS name, COUNT(*) AS total
FROM support_tickets
WHERE tenant_id = #{tenantId}

  AND created_at >= #{startAt}
  AND created_at < #{endAt}
GROUP BY category
ORDER BY total DESC, category ASC
LIMIT #{limit}

SELECT channel AS name, COUNT(*) AS total
FROM support_tickets
WHERE tenant_id = #{tenantId}

  AND created_at >= #{startAt}
  AND created_at < #{endAt}
GROUP BY channel
ORDER BY total DESC, channel ASC
LIMIT #{limit}

WITH RECURSIVE date_series(bucket_date) AS ( SELECT DATE(#{startAt}) UNION ALL SELECT DATE_ADD(bucket_date, INTERVAL 1 DAY) FROM date_series WHERE bucket_date < DATE(DATE_SUB(#{endAt}, INTERVAL 1 DAY)) ) SELECT DATE_FORMAT(ds.bucket_date, '%m-%d') AS date_label, COALESCE(ticket_stats.total, 0) AS total, COALESCE(ticket_stats.resolved, 0) AS resolved, COALESCE(ticket_stats.overdue, 0) AS overdue, COALESCE(event_stats.outgoing_replies, 0) AS outgoing_replies FROM date_series ds LEFT JOIN ( SELECT DATE(created_at) AS bucket_date, COUNT(*) AS total, COALESCE(SUM(CASE WHEN status IN ('RESOLVED', 'CLOSED') THEN 1 ELSE 0 END), 0) AS resolved, COALESCE(SUM(CASE WHEN due_at IS NOT NULL AND due_at < CURRENT_TIMESTAMP(6) AND status NOT IN ('RESOLVED', 'CLOSED') THEN 1 ELSE 0 END), 0) AS overdue FROM support_tickets WHERE tenant_id = #{tenantId}
AND created_at >= #{startAt} AND created_at < #{endAt} GROUP BY DATE(created_at) ) ticket_stats ON ticket_stats.bucket_date = ds.bucket_date LEFT JOIN ( SELECT DATE(created_at) AS bucket_date, COUNT(*) AS outgoing_replies FROM support_ticket_events WHERE tenant_id = #{tenantId}
AND event_type = 'AGENT_REPLY_SENT' AND created_at >= #{startAt} AND created_at < #{endAt} GROUP BY DATE(created_at) ) event_stats ON event_stats.bucket_date = ds.bucket_date ORDER BY ds.bucket_date ASC

SELECT t.assignee_id AS assignee_id, COALESCE(u.display_name, u.email, '未分配') AS assignee_name, COUNT(t.id) AS assigned_tickets, COALESCE(SUM(CASE WHEN t.status NOT IN ('RESOLVED', 'CLOSED') THEN 1 ELSE 0 END), 0) AS open_tickets, COALESCE(SUM(CASE WHEN t.status IN ('RESOLVED', 'CLOSED') THEN 1 ELSE 0 END), 0) AS resolved_tickets, COALESCE(MAX(reply_stats.outgoing_replies), 0) AS outgoing_replies, CAST(ROUND(AVG(CASE WHEN first_reply.first_reply_at IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, t.created_at, first_reply.first_reply_at) ELSE NULL END)) AS SIGNED) AS avg_first_response_minutes, CAST(ROUND( COALESCE(SUM(CASE WHEN t.status IN ('RESOLVED', 'CLOSED') AND t.due_at IS NOT NULL AND t.resolved_at IS NOT NULL AND t.resolved_at <= t.due_at THEN 1 ELSE 0 END), 0) * 100.0 / NULLIF(COALESCE(SUM(CASE WHEN t.status IN ('RESOLVED', 'CLOSED') AND t.due_at IS NOT NULL THEN 1 ELSE 0 END), 0), 0) ) AS SIGNED) AS sla_attainment_rate FROM support_tickets t LEFT JOIN users u ON u.id = t.assignee_id LEFT JOIN ( SELECT ticket_id, MIN(created_at) AS first_reply_at FROM support_ticket_events WHERE tenant_id = #{tenantId}
AND event_type = 'AGENT_REPLY_SENT' GROUP BY ticket_id ) first_reply ON first_reply.ticket_id = t.id LEFT JOIN ( SELECT actor_id, COUNT(*) AS outgoing_replies FROM support_ticket_events WHERE tenant_id = #{tenantId}
AND event_type = 'AGENT_REPLY_SENT' AND created_at >= #{startAt} AND created_at < #{endAt} GROUP BY actor_id ) reply_stats ON reply_stats.actor_id = t.assignee_id WHERE t.tenant_id = #{tenantId}
AND t.created_at >= #{startAt} AND t.created_at < #{endAt} GROUP BY t.assignee_id, u.display_name, u.email ORDER BY assigned_tickets DESC, outgoing_replies DESC, assignee_name ASC LIMIT #{limit}
